/** Equality can narrow a language-valued producer without taking ownership of its observable representative. */
class PackedFiniteLanguageRepresentativeTest {

	static Stream<Arguments> cases() {
		return Stream.of(new String[] { "en", "EN" }, new String[] { "EN", "en" },
				new String[] { "en-gb", "EN-GB" })
				.flatMap(tags -> Stream.of("equal", "reversed", "in", "or")
						.map(shape -> Arguments.of(tags[0], tags[1], shape)));
	}

	@ParameterizedTest(name = "stored={0}, query={1}, shape={2}")
	@MethodSource("cases")
	void aFiniteQueryDriverCannotReplaceTheProducedLanguageRepresentative(String storedTag, String queryTag,
			String shape) {
		Model data = model();
		add(data, "s1", "label", VF.createLiteral("abc", storedTag));
		add(data, "s2", "label", VF.createLiteral("other", storedTag));
		String constant = "\"abc\"@" + queryTag;
		String condition = switch (shape) {
		case "equal" -> "?o = " + constant;
		case "reversed" -> constant + " = ?o";
		case "in" -> "?o IN (" + constant + ")";
		case "or" -> "?o = " + constant + " || ?o = \"absent\"@" + queryTag;
		default -> throw new AssertionError(shape);
		};
		String query = "SELECT ?s ?o (LANG(?o) AS ?language) WHERE { ?s :label ?o FILTER(" + condition + ") }";
		PackedQuery packed = PackedQueryCodec.encodeForPlanning(parse(query));
		for (int relationId = 1; relationId <= packed.relationCount(); relationId++) {
			if (packed.relOperator(relationId) == PackedRelOp.JOIN
					&& (packed.relRuleMask(relationId) & PackedRuleProofs.FINITE_FILTER_VALUES) != 0L) {
				// Every admitted filter alternative must preserve the binding even if costing selects another one.
				assertEquals(List.of("o=\"abc\"@" + storedTag + "|s=urn:t:s1"),
						evaluate(data, PackedPlanMaterializer.materialize(packed, relationId)),
						"a generated finite filter alternative changed its producer's observable term");
			}
		}
		assertPackedPlanPreservesResults(data, query, SUBJECT_LOOKUP_COSTS, null,
				List.of("language=\"" + storedTag + "\"|o=\"abc\"@" + storedTag + "|s=urn:t:s1"));
	}

	@Test
	void representationStableStringFilterKeepsItsFiniteLookupAlternative() {
		Model data = model();
		add(data, "s1", "label", VF.createLiteral("abc"));
		String query = "SELECT ?s ?o WHERE { ?s :label ?o FILTER(?o = \"abc\") }";
		assertTrue((generatedRuleMask(PackedQueryCodec.encodeForPlanning(parse(query)))
				& PackedRuleProofs.FINITE_FILTER_VALUES) != 0L,
				"the finite query-driver optimization remains available for representation-stable terms");
		assertPackedPlanPreservesResults(data, query, SUBJECT_LOOKUP_COSTS, null,
				List.of("o=\"abc\"|s=urn:t:s1"));
	}
}
